SELECT
(SELECT count(*)=5 AND bool_and(c.relrowsecurity AND NOT has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('service_role',c.oid,'SELECT,INSERT,UPDATE,DELETE')) FROM pg_class c WHERE c.oid IN(to_regclass('petro_private.merchant_withdrawals'),to_regclass('petro_private.merchant_withdrawal_allocations'),to_regclass('petro_private.merchant_withdrawal_events'),to_regclass('petro_private.merchant_withdrawal_releases'),to_regclass('petro_private.merchant_withdrawal_commands')))
AND(SELECT count(*)=4 AND bool_and(p.prosecdef AND p.proconfig=ARRAY['search_path=""']::text[] AND has_function_privilege('authenticated',p.oid,'EXECUTE') AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('service_role',p.oid,'EXECUTE')) FROM pg_proc p WHERE p.oid IN(to_regprocedure('public.petro_merchant_withdrawals(uuid,integer)'),to_regprocedure('public.petro_merchant_withdrawal_options(uuid,integer)'),to_regprocedure('public.petro_submit_merchant_withdrawal(uuid,uuid,uuid[],text)'),to_regprocedure('public.petro_review_merchant_withdrawal(uuid,bigint,text,text)')))
AND EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='merchant_withdrawal_refund_adjust' AND tgenabled='O')
AS present;
